import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * Writes docs/configuration/reference.md from the Spring configuration metadata that the build writes
 * for each module, so the page always lists the keys the code has. Usage: {@code java
 * ConfigReference.java <repository>}, after {@code ./mvnw} has compiled every module. A failed check
 * exits with 1 and writes nothing.
 */
final class ConfigReference {

  /** The page this program writes, relative to the repository. */
  private static final String PAGE = "docs/configuration/reference.md";

  /** Where the build writes a module's configuration metadata, relative to the module. */
  private static final String METADATA = "target/classes/META-INF/spring-configuration-metadata.json";

  /** The folders whose modules may have configuration metadata. */
  private static final List<String> MODULE_FOLDERS = List.of("libs", "starters");

  /**
   * A built module with {@code stratum.*} keys, in page order.
   *
   * @param folder the module's folder in the repository
   * @param title the module's heading on the page
   * @param prefix the prefix every key of the module starts with
   * @param page the label of the page that owns the module's keys
   * @param link that page's address, relative to the reference page
   */
  private record Module(String folder, String title, String prefix, String page, String link) {}

  /** Every module with keys. A built module with {@code stratum.*} keys that is not here fails the run. */
  private static final List<Module> MODULES =
      List.of(
          new Module(
              "libs/stratum-core", "Shared properties", "stratum", "Shared settings", "shared-settings.md"),
          new Module(
              "libs/stratum-web", "Web", "stratum.web", "Web → Properties", "../modules/web.md#properties"),
          new Module(
              "starters/stratum-starter-logging",
              "Logging",
              "stratum.logging",
              "Logging → Properties",
              "../../starters/stratum-starter-logging/README.md#properties"),
          new Module(
              "starters/stratum-starter-observability",
              "Observability",
              "stratum.observability",
              "Observability → Properties",
              "../../starters/stratum-starter-observability/README.md#properties"),
          new Module(
              "libs/stratum-http-client",
              "HTTP client",
              "stratum.http-client",
              "HTTP client → Properties",
              "../modules/http-client.md#properties"),
          new Module(
              "starters/stratum-starter-data-jpa",
              "Data",
              "stratum.data",
              "Data → Properties",
              "../modules/data-jpa.md#properties"),
          new Module(
              "starters/stratum-starter-cache",
              "Cache",
              "stratum.cache",
              "Cache → Properties",
              "../modules/cache.md#properties"));

  /** The page's opening, up to its table of contents. */
  private static final String INTRO =
      """
      <!-- Generated by .github/config-reference/ConfigReference.java. Do not edit: run it again. -->
      # Configuration reference

      **Status: Built.** Every `stratum.*` key of the built modules, generated from the configuration
      metadata the build writes, so the page always matches the code. Planned modules have no keys yet.

      [← Documentation home](../README.md)

      Each module section links the module's own page, which explains its keys with examples and lists
      the Spring Boot keys the module gives a default. How to set a key is in
      [Configuration basics](basics.md); the instance ID and a complete example are in
      [Shared settings](shared-settings.md).

      ## Contents

      """;

  /** A Javadoc {@code @code} or {@code @link} tag, whose text becomes a code span. */
  private static final Pattern JAVADOC_CODE = Pattern.compile("\\{@(?:code|link) ([^}]*)}");

  /** A package name or an outer class before a type name, left out of the Type column. */
  private static final Pattern QUALIFIER = Pattern.compile("\\b[a-z]\\w*\\.|\\w+\\$");

  /** The characters Markdown would read as formatting or as a table cell's end. */
  private static final Pattern MARKDOWN = Pattern.compile("([\\\\`*_|<\\[\\]])");

  /** The repository root that holds the modules and docs/. */
  private final Path repository;

  private ConfigReference(Path repository) {
    this.repository = repository;
  }

  /**
   * Writes the page and exits with 1 on any failed check.
   *
   * @param args the repository root
   */
  public static void main(String[] args) {
    if (args.length != 1) {
      System.err.println("usage: java ConfigReference.java <repository>");
      System.exit(2);
    }
    try {
      new ConfigReference(Path.of(args[0])).run();
    } catch (IllegalStateException | UncheckedIOException failure) {
      System.err.println("config-reference: error: " + failure.getMessage());
      System.exit(1);
    }
  }

  /** Reads every module's metadata, checks it, then writes the page. */
  private void run() {
    checkEveryModuleListed();
    var sections = new LinkedHashMap<Module, Map<String, List<Map<String, Object>>>>();
    MODULES.forEach(module -> sections.put(module, groups(module)));
    var contents = new StringBuilder(INTRO);
    var body = new StringBuilder();
    sections.forEach((module, groups) -> addModule(module, groups, contents, body));
    write(contents.append(body).toString());
    long keys =
        sections.values().stream().flatMap(groups -> groups.values().stream()).mapToLong(List::size).sum();
    System.out.println("config-reference: " + keys + " keys written to " + PAGE);
  }

  /** Fails when a module with {@code stratum.*} keys has no entry in {@link #MODULES}. */
  private void checkEveryModuleListed() {
    var listed = MODULES.stream().map(Module::folder).collect(Collectors.toSet());
    MODULE_FOLDERS.stream()
        .map(repository::resolve)
        .filter(Files::isDirectory)
        .flatMap(this::folders)
        .map(folder -> repository.relativize(folder).toString().replace('\\', '/'))
        .filter(folder -> !listed.contains(folder))
        .filter(folder -> Files.exists(repository.resolve(folder).resolve(METADATA)))
        .filter(folder -> !stratumKeys(folder).isEmpty())
        .findFirst()
        .ifPresent(
            folder -> {
              throw new IllegalStateException(folder + " has stratum.* keys but no entry in MODULES");
            });
  }

  /**
   * Sorts a module's keys into its groups: each key goes to the longest group name it starts with.
   *
   * @param module the module
   * @return the keys of each group that has any, by group name
   */
  private Map<String, List<Map<String, Object>>> groups(Module module) {
    if (!Files.exists(repository.resolve(module.folder()).resolve(METADATA))) {
      throw new IllegalStateException(
          module.folder() + "/" + METADATA + " is missing; build with ./mvnw first");
    }
    var names = new TreeSet<String>();
    names.add(module.prefix());
    objects(metadata(module.folder()).get("groups")).stream()
        .map(group -> (String) group.get("name"))
        .filter(name -> name.startsWith(module.prefix() + "."))
        .forEach(names::add);
    var groups = new LinkedHashMap<String, List<Map<String, Object>>>();
    names.forEach(name -> groups.put(name, new ArrayList<>()));
    stratumKeys(module.folder()).forEach(property -> groups.get(groupOf(module, names, property)).add(property));
    groups.values().removeIf(List::isEmpty);
    Comparator<Map<String, Object>> byKey = Comparator.comparing(property -> (String) property.get("name"));
    groups.values().forEach(keys -> keys.sort(byKey));
    return groups;
  }

  /**
   * Returns the group of one key: the longest group name the key starts with.
   *
   * @param module the module the key belongs to
   * @param names the module's group names
   * @param property the key's metadata
   * @return the group name
   */
  private String groupOf(Module module, TreeSet<String> names, Map<String, Object> property) {
    String key = (String) property.get("name");
    if (!key.startsWith(module.prefix() + ".")) {
      throw new IllegalStateException(module.folder() + ": " + key + " does not start with " + module.prefix());
    }
    return names.descendingSet().stream().filter(name -> key.startsWith(name + ".")).findFirst().orElseThrow();
  }

  /** Adds a module's entries to the table of contents and its section, with one table per group. */
  private void addModule(
      Module module,
      Map<String, List<Map<String, Object>>> groups,
      StringBuilder contents,
      StringBuilder body) {
    contents.append("- [").append(module.title()).append("](#").append(anchor(module.title())).append(")\n");
    body.append("\n## ").append(module.title()).append("\n\n");
    body.append("Module page: [").append(module.page()).append("](").append(module.link()).append(").\n");
    groups.forEach((group, keys) -> addGroup(group, keys, contents, body));
  }

  /** Adds a group's entry to the table of contents and its table to the section. */
  private void addGroup(String group, List<Map<String, Object>> keys, StringBuilder contents, StringBuilder body) {
    contents.append("  - [`").append(group).append("`](#").append(anchor(group)).append(")\n");
    body.append("\n### `").append(group).append("`\n\n");
    body.append("| Key | Type | Default | Description |\n| --- | --- | --- | --- |\n");
    keys.forEach(property -> body.append(row(property)));
  }

  /** Returns one table row: the key, its type, its default and its description. */
  private String row(Map<String, Object> property) {
    String type = QUALIFIER.matcher(String.valueOf(property.get("type"))).replaceAll("").replace(",", ", ");
    return "| `"
        + property.get("name")
        + "` | `"
        + type
        + "` | "
        + defaultValue(property.get("defaultValue"))
        + " | "
        + description(String.valueOf(property.getOrDefault("description", "")))
        + " |\n";
  }

  /** Returns a default as code, a list joined with commas, or "none" when the metadata has none. */
  private String defaultValue(Object value) {
    if (value == null) {
      return "none";
    }
    if (value instanceof List<?> values) {
      String joined = values.stream().map(String::valueOf).collect(Collectors.joining(", "));
      return values.isEmpty() ? "*(empty)*" : "`" + joined + "`";
    }
    return "`" + value + "`";
  }

  /** Returns a description on one line, with Javadoc code tags as code spans and Markdown escaped. */
  private String description(String text) {
    String line = text.strip().replaceAll("\\s+", " ");
    return Arrays.stream(JAVADOC_CODE.splitWithDelimiters(line, 0))
        .map(this::descriptionPart)
        .collect(Collectors.joining());
  }

  /** Returns a Javadoc code tag as a code span, and any other text with Markdown escaped. */
  private String descriptionPart(String part) {
    Matcher code = JAVADOC_CODE.matcher(part);
    return code.matches() ? "`" + code.group(1) + "`" : escape(part);
  }

  /** Escapes the characters Markdown would read as formatting. */
  private String escape(String text) {
    return MARKDOWN.matcher(text).replaceAll("\\\\$1");
  }

  /**
   * Returns the anchor GitHub gives a heading: lower case, without punctuation, spaces as hyphens.
   *
   * @param heading the heading's text, without its backticks
   * @return the anchor, without the {@code #}
   */
  private String anchor(String heading) {
    return heading.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9 _-]", "").replace(' ', '-');
  }

  /** Returns a module's properties whose key starts with {@code stratum.}. */
  private List<Map<String, Object>> stratumKeys(String folder) {
    return objects(metadata(folder).get("properties")).stream()
        .filter(property -> ((String) property.get("name")).startsWith("stratum."))
        .toList();
  }

  /** Reads and parses a module's metadata file. */
  @SuppressWarnings("unchecked")
  private Map<String, Object> metadata(String folder) {
    String file = folder + "/" + METADATA;
    try {
      String json = Files.readString(repository.resolve(file), StandardCharsets.UTF_8);
      return (Map<String, Object>) new Json(file, json).document();
    } catch (IOException failure) {
      throw new UncheckedIOException("cannot read " + file, failure);
    }
  }

  /** Returns a JSON array of objects as a list, or an empty list when it is absent. */
  @SuppressWarnings("unchecked")
  private List<Map<String, Object>> objects(Object array) {
    return array == null ? List.of() : (List<Map<String, Object>>) array;
  }

  /** Lists the folders inside a folder, sorted by name. */
  private Stream<Path> folders(Path folder) {
    try (Stream<Path> entries = Files.list(folder)) {
      return entries.filter(Files::isDirectory).sorted().toList().stream();
    } catch (IOException failure) {
      throw new UncheckedIOException("cannot list " + folder, failure);
    }
  }

  /** Writes the page as UTF-8. */
  private void write(String content) {
    Path page = repository.resolve(PAGE);
    try {
      Files.createDirectories(page.getParent());
      Files.writeString(page, content, StandardCharsets.UTF_8);
    } catch (IOException failure) {
      throw new UncheckedIOException("cannot write " + page, failure);
    }
  }
}
